import { Navigate, Outlet } from "react-router-dom"; 
<import>Navigate, Outlet</import>

const PrivateRoute = () => {
  const isLoggedIn = localStorage.getItem("token");
  return isLoggedIn ? <Outlet /> : <Navigate to="/LoginSignup" />;
};

export default PrivateRoute;
